function mkInterp(pts) {
  var n = pts.length, xs = [], ys = [], i;
  for (i = 0; i < n; i++) { xs.push(pts[i][0]); ys.push(pts[i][1]); }
  var d = [], m = [];
  for (i = 0; i < n - 1; i++) d.push((ys[i + 1] - ys[i]) / (xs[i + 1] - xs[i]));
  m.push(d[0]);
  for (i = 1; i < n - 1; i++) m.push(d[i - 1] * d[i] <= 0 ? 0 : (d[i - 1] + d[i]) / 2);
  m.push(d[n - 2]);
