/* ---------- shape of the plate (monotone cubic interpolation) ---------- */
function mkInterp(pts) {
  var n = pts.length, xs = [], ys = [], i;
  for (i = 0; i < n; i++) { xs.push(pts[i][0]); ys.push(pts[i][1]); }
  var d = [], m = [];
  for (i = 0; i < n - 1; i++) d.push((ys[i + 1] - ys[i]) / (xs[i + 1] - xs[i]));
  m.push(d[0]);
  for (i = 1; i < n - 1; i++) m.push(d[i - 1] * d[i] <= 0 ? 0 : (d[i - 1] + d[i]) / 2);
  m.push(d[n - 2]);
  for (i = 0; i < n - 1; i++) {
    if (d[i] === 0) { m[i] = 0; m[i + 1] = 0; continue; }
    var a1 = m[i] / d[i], b1 = m[i + 1] / d[i], s = a1 * a1 + b1 * b1;
    if (s > 9) { var t = 3 / Math.sqrt(s); m[i] = t * a1 * d[i]; m[i + 1] = t * b1 * d[i]; }
  }
  return function (x) {
    if (x <= xs[0]) return ys[0];
    if (x >= xs[n - 1]) return ys[n - 1];
    var lo = 0, hi = n - 1;
    while (hi - lo > 1) { var mid = (lo + hi) >> 1; if (xs[mid] <= x) lo = mid; else hi = mid; }
    var h = xs[hi] - xs[lo], u = (x - xs[lo]) / h, u2 = u * u, u3 = u2 * u;
    return (2 * u3 - 3 * u2 + 1) * ys[lo] + (u3 - 2 * u2 + u) * h * m[lo] +
           (-2 * u3 + 3 * u2) * ys[hi] + (u3 - u2) * h * m[hi];
  };
}
var tL = mkInterp([[0, 0.55], [0.012, 0.49], [0.04, 0.395], [0.09, 0.29], [0.16, 0.19],
  [0.26, 0.115], [0.38, 0.075], [0.50, 0.075], [0.60, 0.105], [0.70, 0.145],
  [0.80, 0.19], [0.88, 0.235], [0.94, 0.275], [0.975, 0.30], [1, 0.33]]);
var tR = mkInterp([[0, 0.55], [0.012, 0.62], [0.04, 0.72], [0.09, 0.825], [0.17, 0.915],
  [0.28, 0.975], [0.40, 1.0], [0.52, 0.99], [0.62, 0.945], [0.70, 0.875], [0.77, 0.78],
  [0.83, 0.665], [0.885, 0.555], [0.93, 0.465], [0.97, 0.39], [1, 0.33]]);

