function yPix(u) { return PY_A + u * (PY_B - PY_A); }
function depthOf(u) { return D_A + u * (D_B - D_A); }
function wM(u) { return Math.max(0, tR(u) - tL(u)) * (PX1 - PX0) / PPM; }
