  }
  if (band >= 17) {
    var show = (n <= 6) ? [] : [1, 2, 3, n];
    if (n <= 6) { for (k = 1; k <= n; k++) show.push(k); }
    if (show.indexOf(kSel) === -1) show.push(kSel);
    for (var j = 0; j < show.length; j++) {
      k = show[j]; var uc = (k - 0.5) / n, yc = yPix(uc);
      var cx = (xPix(tL(uc)) + xPix(tR(uc))) / 2;
      txt(g, 'A' + sub(k), cx, yc, { size: 19, halo: 3.5, fill: k === kSel ? '#8a4b06' : INK });
    }
    if (n > 5) {
      var ymid = yPix(0.62);
      for (var e = 0; e < 3; e++) g.circle(4.5).center(xPix(0.55), ymid + 15 * e).fill(INK);
    }
  }
}

function drawPanelC(g) {
  var n = state.n, k = state.k, u0 = (k - 1) / n, u1 = k / n, us = (k - 0.5) / n;
  var y0 = yPix(u0), y1 = yPix(u1), ys = yPix(us);
  var xl = xPix(tL(us)), xr = xPix(tR(us));
  drawBlob(g);
  var rect = g.rect(xr - xl, Math.max(2.5, y1 - y0)).move(xl, y0)
    .fill(GREEN).opacity(0.88).stroke({ color: INK, width: 1.8 });
  hookup(rect, 'ΔF ≈ ρ·h·w·Δx = ' + kN(stripF(k, n)) + ' kN',
    'The kth strip', 'Replace the curved band by a rectangle of width w(x*ₖ) and thickness Δxₖ sitting at the single depth h(x*ₖ). Its pressure is essentially constant, so its force is simply ρ·h(x*ₖ)·w(x*ₖ)·Δxₖ.');
  dashLine(g, ys, AX, xr);
  g.circle(11).center(xl, ys).fill(INK);
  g.circle(11).center(xr, ys).fill(INK);
  g.circle(11).center(AX, ys).fill(INK);
  tickLab(g, PY_A, 'a');
  tickLab(g, PY_B, 'b');
  txt(g, 'x*' + '\u2096', AX - 50, ys, { size: 21, anchor: 'end', halo: 3 });
  if (y1 - y0 >= 22) {
    txt(g, 'x' + sub(k) + '₋₁', AX - 10, y0 - 11, { size: 17, anchor: 'end', halo: 3 });
    txt(g, 'x' + sub(k), AX - 10, y1 + 11, { size: 17, anchor: 'end', halo: 3 });
  }
  var axp = xr + 16;
  g.line(axp, y0 - 24, axp, y0).stroke({ color: INK, width: 1.8 });
  arrowHead(g, axp, y0, 1, INK, 5.5);
  g.line(axp, y1 + 24, axp, y1).stroke({ color: INK, width: 1.8 });
  arrowHead(g, axp, y1, -1, INK, 5.5);
  txt(g, 'Δx' + '\u2096', axp + 7, (y0 + y1) / 2, { size: 17, anchor: 'start', halo: 4 });
  g.line(xr + 30, ys, 537, ys).stroke({ color: INK, width: 1.4 });
  vDbl(g, 525, SY + 3, ys);
  var hl = txt(g, 'h(x*' + '\u2096' + ')', 533, (SY + ys) / 2, { size: 19, anchor: 'start', halo: 4 });
  hookup(hl, 'h(x*ₖ) = ' + depthOf(us).toFixed(2) + ' m', 'Depth of the sample level',
    'Every point of this thin strip is at almost the same depth h(x*ₖ), so the pressure over the strip is nearly the constant ρ·h(x*ₖ).');
  var yw = 358;
  g.line(xl, yw - 10, xl, yw + 10).stroke({ color: INK, width: 2 });
  g.line(xr, yw - 10, xr, yw + 10).stroke({ color: INK, width: 2 });
  g.line(xl, yw, xr, yw).stroke({ color: INK, width: 1.8 });
  hHead(g, xl, yw, -1); hHead(g, xr, yw, 1);
  txt(g, 'w(x*' + '\u2096' + ')', (xl + xr) / 2, yw, { size: 19, halo: 5 });
}

function drawPanelAnim(g) {
  var n = state.n, m = (state.accumM == null) ? n : state.accumM, k;
  drawBlob(g);
  for (k = 1; k <= n; k++) {
    var us = (k - 0.5) / n, xl = xPix(tL(us)), xr = xPix(tR(us));
    var y0 = yPix((k - 1) / n), y1 = yPix(k / n);
    var r = g.rect(Math.max(1, xr - xl), Math.max(1.2, y1 - y0)).move(xl, y0)
      .fill(k <= m ? GREENDK : '#ffe9c8').opacity(k <= m ? 0.85 : 0.75)
      .stroke({ color: k <= m ? '#1d6b4d' : '#c79a5a', width: (y1 - y0) > 4 ? 0.8 : 0.3 });
    (function (kk) {
      r.css('cursor', 'pointer')
        .on('mousemove', function (e) { showTooltip('strip ' + kk + ':  ρ·h·w·Δx = ' + kN(stripF(kk, n)) + ' kN', e); })
        .on('mouseleave', hideTooltip);
    })(k);
  }
  if (m > 0 && m < n) dashLine(g, yPix(m / n), AX, xPix(tR(m / n)) + 8);
  tickLab(g, PY_A, 'a'); tickLab(g, PY_B, 'b');
  var run = riemann(n, m);
  var gx = 508, gy0 = 70, gy1 = 330, gw = 26;
  g.rect(gw, gy1 - gy0).move(gx, gy0).fill('#ffffff').opacity(0.9).stroke({ color: '#333', width: 1.2 });
  var frac = Math.max(0, Math.min(1, run / EXACT));
  var bar = g.rect(gw, (gy1 - gy0) * frac).move(gx, gy0).fill(GREENDK).opacity(0.9);
  hookup(bar, 'running total = ' + kN(run) + ' kN  of  ' + kN(EXACT) + ' kN',
    'Accumulating the force', 'The bar is the running sum of the strip forces, added from the surface downward. It climbs fastest where the plate is both wide and deep, because each strip contributes ρ·h·w·Δx.');
  txt(g, 'Σ', gx + gw / 2, gy0 - 15, { size: 17 });
  txt(g, kN(run) + ' kN', gx + gw / 2, gy1 + 16, { size: 12, style: 'normal' });
  txt(g, 'accumulated ' + m + ' of ' + n + ' strips', AX + 14, 48,
    { size: 15, style: 'normal', anchor: 'start', halo: 4 });
}

function drawReadout(g) {
  var n = state.n, k = state.k, us = (k - 0.5) / n;
  var m = (state.view === 'anim' && state.accumM != null) ? state.accumM : n;
  var sum = riemann(n, m), full = riemann(n, n);
  var err = Math.abs(full - EXACT) / EXACT * 100;
  var box = g.rect(FIGW - 40, READH - 26).move(20, 6).radius(7)
    .fill('#f4fafd').stroke({ color: '#9fc4d6', width: 1.2 });
  hookup(box, 'Riemann sum vs. exact integral', 'From sum to integral',
    'Each strip contributes ρ·h(x*ₖ)·w(x*ₖ)·Δxₖ. Adding them gives the Riemann sum shown here; letting n → ∞ (Δxₖ → 0) makes the sum converge to the exact fluid force F = ∫ₐᵇ ρ h(x) w(x) dx, and the error readout collapses to zero.');
  txt(g, 'F ≈ Σ ρ h(x*\u2096) w(x*\u2096) Δx\u2096     ⟶     F = ∫ₐᵇ ρ h(x) w(x) dx', FIGW / 2, 36, { size: 20 });
  var l2 = 'n = ' + n + '     Σ = ' + kN(sum) + ' kN' + (m < n ? ' (' + m + ' of ' + n + ' strips)' : '') +
    '     exact = ' + kN(EXACT) + ' kN     error = ' + err.toFixed(2) + '%';
  txt(g, l2, FIGW / 2, 66, { size: 14, style: 'normal' });
  var l3 = 'strip k = ' + k + ':   h(x*\u2096) = ' + depthOf(us).toFixed(2) + ' m,   w(x*\u2096) = ' +
    wM(us).toFixed(2) + ' m,   Δx\u2096 = ' + ((D_B - D_A) / n).toFixed(2) + ' m   →   ΔF = ' + kN(stripF(k, n)) + ' kN';
  txt(g, l3, FIGW / 2, 90, { size: 14, style: 'normal', fill: '#8a4b06' });
}

/* ---------- render ---------- */
function render() {
  draw.clear();
  WATER = draw.gradient('linear', function (add) {
    add.stop(0, '#eaf7fd'); add.stop(0.55, '#b9e3f5'); add.stop(1, '#79c6e9');
  }).from(0, 0).to(0, 1);
  var views = (state.view === 'all') ? ['a', 'b', 'c'] : [state.view];
  var totalH = views.length * (PANH + CAPH) + READH;
  draw.viewbox(0, 0, FIGW, totalH);
  for (var i = 0; i < views.length; i++) {
    var v = views[i];
    var g = draw.group().translate(0, i * (PANH + CAPH));
    panelFrame(g);
    if (v === 'a') drawPanelA(g);
    else if (v === 'b') drawPanelB(g);
    else if (v === 'c') drawPanelC(g);
    else drawPanelAnim(g);
    var cap = v === 'a' ? '(a)' : v === 'b' ? '(b)' : v === 'c' ? '(c)' : '(d)  accumulating the strip forces';
    txt(g, cap, FIGW / 2, PANH + 28, { size: v === 'anim' ? 19 : 26 });
  }
  drawReadout(draw.group().translate(0, views.length * (PANH + CAPH)));
}

/* ---------- controls ---------- */
function setN(v) {
  state.n = Math.max(1, Math.min(60, Math.round(v)));
  var ni = document.getElementById('nStripsInput'); if (ni) ni.value = state.n;
  var no = document.getElementById('nStripsVal'); if (no) no.value = state.n;
  var ki = document.getElementById('stripIndexInput');
  if (ki) ki.max = state.n;
  if (state.k > state.n) setK(state.n);
  if (state.accumM != null) state.accumM = Math.min(state.accumM, state.n);
}
function setK(v) {
  state.k = Math.max(1, Math.min(state.n, Math.round(v)));
  var ki = document.getElementById('stripIndexInput'); if (ki) ki.value = state.k;
  var ko = document.getElementById('stripIndexVal'); if (ko) ko.value = state.k;
}
function update_nStrips(v) { stopAnim(); setN(v); if (state.view === 'anim') state.accumM = state.n; render(); }
function update_stripIndex(v) { setK(v); render(); }
function toggle_panelView(v) {
  stopAnim(); state.view = v;
  if (v === 'anim' && state.accumM == null) state.accumM = state.n;
  render();
}
function stopAnim() {
  if (animTimer) { clearInterval(animTimer); animTimer = null; }
  var b = document.getElementById('accumBtn'); if (b) b.textContent = '▶ Accumulate strip forces';
}
function startAnim() {
  stopAnim();
  state.accumM = 0; render();
  var b = document.getElementById('accumBtn'); if (b) b.textContent = '■ Stop';
  animTimer = setInterval(function () {
    state.accumM++;
    if (state.accumM >= state.n) { state.accumM = state.n; stopAnim(); }
    render();
  }, Math.max(40, Math.min(200, 2600 / state.n)));
}
function trigger_accumulate() {
  if (animTimer) { stopAnim(); state.accumM = state.n; render(); return; }
  if (state.view !== 'anim') {
    state.view = 'anim';
    var sel = document.getElementById('panelViewInput'); if (sel) sel.value = 'anim';
  }
  startAnim();
}

/* ---------- guided demo ---------- */
var STEPS = [
  { t: 'The whole submerged plate',
    n: 'A flat plate hangs vertically in the fluid between depths a and b. At any depth x it has width w(x) and lies under depth h(x) of fluid — but pressure is not constant over the plate, so force is not just pressure × area.',
    s: { view: 'all', n: 8, k: 3 } },
  { t: 'Slice it into horizontal strips',
    n: 'Partition the depth interval a = x₀ &lt; x₁ &lt; … &lt; xₙ = b. Each horizontal band Aₖ is thin enough that the depth — and therefore the pressure — barely changes across it.',
    s: { view: 'b', n: 8, k: 3 } },
  { t: 'Zoom in on the kth strip',
    n: 'Pick a sample depth x*ₖ inside [xₖ₋₁, xₖ]. Approximate the strip by a rectangle of width w(x*ₖ) and height Δxₖ at uniform depth h(x*ₖ), so its force is ρ·h(x*ₖ)·w(x*ₖ)·Δxₖ.',
    s: { view: 'c', n: 8, k: 4 } },
  { t: 'Walk down the plate',
    n: 'Slide k from top to bottom and watch h(x*ₖ) grow steadily while w(x*ₖ) rises and falls with the shape. Deep, wide strips dominate the total force.',
    s: { view: 'all', n: 8, k: 7 } },
  { t: 'Add up the strips',
    n: 'Accumulating the strip forces from the surface downward builds the Riemann sum F ≈ Σ ρ h(x*ₖ) w(x*ₖ) Δxₖ; the running total climbs fastest through the widest, deepest part of the plate.',
    s: { view: 'anim', n: 8, k: 8 } },
  { t: 'Refine the partition',
    n: 'Raise n and the rectangles fill the blob almost exactly; the sum settles onto the exact value F = ∫ₐᵇ ρ h(x) w(x) dx and the error readout collapses toward zero.',
    s: { view: 'anim', n: 48, k: 24 } }
];
var stepIdx = 0;
function applyStep(i) {
  stepIdx = (i + STEPS.length) % STEPS.length;
  var st = STEPS[stepIdx];
  stopAnim();
  state.view = st.s.view;
  var sel = document.getElementById('panelViewInput'); if (sel) sel.value = st.s.view;
  setN(st.s.n); setK(st.s.k);
  state.accumM = state.n;
  document.getElementById('demoNarration').innerHTML =
    '<b>' + (stepIdx + 1) + '. ' + st.t + '</b><br>' + st.n;
  document.getElementById('stepLabel').textContent = 'Step ' + (stepIdx + 1) + ' / ' + STEPS.length;
  render();
  if (st.s.view === 'anim') startAnim();
}
function nextStep() { applyStep(stepIdx + 1); }
function prevStep() { applyStep(stepIdx - 1); }

/* ---------- init ---------- */
setN(8); setK(3);
document.getElementById('demoNarration').innerHTML = '<b>1. ' + STEPS[0].t + '</b><br>' + STEPS[0].n;
document.getElementById('stepLabel').textContent = 'Step 1 / ' + STEPS.length;
render();
window.__markRendered();
// @FIGURE_CODE_END

