// @FIGURE_CODE_BEGIN
/* ------------------------------------------------------------------ *
 *  Fluid force on a submerged plate — Riemann sum of horizontal strips
 * ------------------------------------------------------------------ */
var FIGW = 620, PANH = 330, CAPH = 38, BLOCK = PANH + CAPH, READH = 92;
var SY = 20, AX = 88, RIGHT = 612;
var PY_A = 74, PY_B = 262, PX0 = 170, PX1 = 445;
var D_A = 2, D_B = 8, RHOG = 9810;
var PPM = (PY_B - PY_A) / (D_B - D_A);          // pixels per metre (both axes)

var ORANGE = '#fbd196', TEAL = '#3ea7cb', RED = '#f2666c',
    GREEN = '#bfe2cd', GREENDK = '#3ba57c', INK = '#111';

var draw = SVG().addTo(document.getElementById('container')).size('100%', '100%');
var WATER = null;

function clamp(v, a, b) { return Math.max(a, Math.min(b, v)); }

/* ---------------- bean-shaped plate outline ---------------------- */
var RAW = [
  [0.50, 0.02], [0.68, 0.00], [0.85, 0.08], [0.95, 0.24], [0.99, 0.42],
  [0.96, 0.60], [0.88, 0.73], [0.77, 0.80], [0.68, 0.78], [0.60, 0.70],
  [0.53, 0.74], [0.45, 0.85], [0.36, 0.94], [0.26, 0.97], [0.16, 0.92],
  [0.07, 0.80], [0.02, 0.64], [0.01, 0.46], [0.05, 0.30], [0.14, 0.16],
  [0.27, 0.06], [0.38, 0.02]
];
function sampleClosed(pts, per) {
  var out = [], n = pts.length, i, j;
  for (i = 0; i < n; i++) {
    var p0 = pts[(i - 1 + n) % n], p1 = pts[i], p2 = pts[(i + 1) % n], p3 = pts[(i + 2) % n];
    for (j = 0; j < per; j++) {
      var t = j / per, t2 = t * t, t3 = t2 * t;
      var x = 0.5 * (2 * p1[0] + (-p0[0] + p2[0]) * t + (2 * p0[0] - 5 * p1[0] + 4 * p2[0] - p3[0]) * t2 + (-p0[0] + 3 * p1[0] - 3 * p2[0] + p3[0]) * t3);
      var y = 0.5 * (2 * p1[1] + (-p0[1] + p2[1]) * t + (2 * p0[1] - 5 * p1[1] + 4 * p2[1] - p3[1]) * t2 + (-p0[1] + 3 * p1[1] - 3 * p2[1] + p3[1]) * t3);
      out.push([x, y]);
    }
  }
  return out;
}
var POLY = (function () {
  var p = sampleClosed(RAW, 14), i;
  var x0 = 1e9, x1 = -1e9, y0 = 1e9, y1 = -1e9;
  for (i = 0; i < p.length; i++) {
    if (p[i][0] < x0) x0 = p[i][0]; if (p[i][0] > x1) x1 = p[i][0];
    if (p[i][1] < y0) y0 = p[i][1]; if (p[i][1] > y1) y1 = p[i][1];
  }
  for (i = 0; i < p.length; i++) { p[i][0] = (p[i][0] - x0) / (x1 - x0); p[i][1] = (p[i][1] - y0) / (y1 - y0); }
  return p;
})();
function bxTo(b) { return PX0 + b * (PX1 - PX0); }
function byTo(u) { return PY_A + u * (PY_B - PY_A); }
var BLOBD = (function () {
  var d = 'M' + bxTo(POLY[0][0]).toFixed(2) + ',' + byTo(POLY[0][1]).toFixed(2);
  for (var i = 1; i < POLY.length; i++) d += 'L' + bxTo(POLY[i][0]).toFixed(2) + ',' + byTo(POLY[i][1]).toFixed(2);
  return d + 'Z';
})();
function rowXs(u) {
  u = clamp(u, 0.0008, 0.9992);
  var xs = [], N = POLY.length, i;
  for (i = 0; i < N; i++) {
    var a = POLY[i], b = POLY[(i + 1) % N];
    if ((a[1] <= u && b[1] > u) || (b[1] <= u && a[1] > u)) {
      var t = (u - a[1]) / (b[1] - a[1]);
      xs.push(a[0] + t * (b[0] - a[0]));
    }
  }
  xs.sort(function (p, q) { return p - q; });
  return xs;
}
function spanPix(u) {
  var xs = rowXs(u);
  if (!xs.length) return { a: bxTo(0.5), b: bxTo(0.5), xs: [] };
  return { a: bxTo(xs[0]), b: bxTo(xs[xs.length - 1]), xs: xs };
}
function widthM(u) {
  var xs = rowXs(u), s = 0;
  for (var i = 0; i + 1 < xs.length; i += 2) s += (xs[i + 1] - xs[i]);
  return s * (PX1 - PX0) / PPM;
}
function depthOf(u) { return D_A + u * (D_B - D_A); }
function stripF(k, n) { var u = (k - 0.5) / n; return RHOG * depthOf(u) * widthM(u) * (D_B - D_A) / n; }
function riemann(n, m) { if (m == null) m = n; var s = 0; for (var k = 1; k <= m; k++) s += stripF(k, n); return s; }
var EXACT = integrateSimpson(function (u) { return RHOG * depthOf(u) * widthM(u) * (D_B - D_A); }, 0.0005, 0.9995, 2000);
function kN(v) { return (v / 1000).toFixed(0); }
function sub(v) { var s = '' + v, o = '', mp = '₀₁₂₃₄₅₆₇₈₉'; for (var i = 0; i < s.length; i++) o += mp[+s[i]]; return o; }

/* ---------------- small drawing helpers -------------------------- */
function txt(g, s, x, y, opt) {
  opt = opt || {};
  var t = g.text(s);
  t.font({ family: 'Georgia,"Times New Roman",serif', size: opt.size || 20,
           style: opt.style || 'italic', weight: opt.weight || 'normal',
           anchor: opt.anchor || 'middle', leading: 1 });
  t.fill(opt.fill || INK);
  t.attr('dominant-baseline', 'central');
  t.attr('x', x); t.attr('y', y);
  var ts = t.node.querySelector('tspan');
  if (ts) { ts.setAttribute('x', x); ts.setAttribute('dy', 0); }
  if (opt.halo) t.attr({ 'paint-order': 'stroke', stroke: '#fff', 'stroke-width': opt.halo, 'stroke-linejoin': 'round' });
  return t;
}
function hookup(el, tip, ttl, body) {
  el.css('cursor', 'pointer')
    .on('mousemove', function (e) { showTooltip(tip, e); })
    .on('mouseleave', hideTooltip)
    .on('click', function () { showPopup(ttl, body); });
  return el;
}
function vHead(g, x, y, dir, color, s) {
  s = s || 6;
  g.polygon([[x - s * 0.8, y - dir * s * 1.7], [x + s * 0.8, y - dir * s * 1.7], [x, y]]).fill(color || INK);
}
function hHead(g, x, y, dir, color, s) {
  s = s || 6;
  g.polygon([[x - dir * s * 1.7, y - s * 0.8], [x - dir * s * 1.7, y + s * 0.8], [x, y]]).fill(color || INK);
}
function vDbl(g, x, y1, y2, color, w) {
  g.line(x, y1, x, y2).stroke({ color: color || INK, width: w || 2 });
  vHead(g, x, y1, -1, color); vHead(g, x, y2, 1, color);
}
function dashLine(g, y, x1, x2, w) {
  g.line(x1, y, x2, y).stroke({ color: RED, width: w || 2.4, dasharray: '10,7' });
