  hookup(rect, 'ΔF ≈ ρ·h·w·Δx = ' + kN(stripF(k, n)) + ' kN',
    'The kth strip',
    'Replace the curved band by a rectangle of width w(x*ₖ) and thickness Δxₖ sitting at the single depth h(x*ₖ). Its pressure is essentially constant, so its force is simply ρ·h(x*ₖ)·w(x*ₖ)·Δxₖ.');
  g.line(sp.a, y0, sp.b, y0).stroke({ color: INK, width: 1.8 });
  g.line(sp.a, y1, sp.b, y1).stroke({ color: INK, width: 1.8 });
  g.line(sp.a, y0, sp.a, y1).stroke({ color: INK, width: 1.4 });
  g.line(sp.b, y0, sp.b, y1).stroke({ color: INK, width: 1.4 });
  dashLine(g, ys, AX, sp.b);
  g.circle(11).center(sp.a, ys).fill(INK);
  g.circle(11).center(sp.b, ys).fill(INK);
  g.circle(11).center(AX, ys).fill(INK);
  tickLab(g, PY_A, 'a');
  tickLab(g, PY_B, 'b');
  txt(g, 'x*ₖ', AX - 17, ys, { size: 23, anchor: 'end', halo: 3.5 });
  if (y1 - y0 >= 16) {
    txt(g, 'xₖ₋₁', AX + 9, y0 - 11, { size: 17, anchor: 'start', halo: 3.5 });
    txt(g, 'xₖ', AX + 9, y1 + 11, { size: 17, anchor: 'start', halo: 3.5 });
  }
  var axp = sp.b + 15;
  g.line(axp, y0 - 22, axp, y0).stroke({ color: INK, width: 1.7 });
  vHead(g, axp, y0, 1, INK, 5);
  g.line(axp, y1 + 22, axp, y1).stroke({ color: INK, width: 1.7 });
  vHead(g, axp, y1, -1, INK, 5);
  txt(g, 'Δxₖ', axp + 8, (y0 + y1) / 2, { size: 18, anchor: 'start', halo: 4.5 });
  g.line(axp + 30, ys, 516, ys).stroke({ color: INK, width: 1.3 });
  vDbl(g, 522, SY + 3, ys);
  var hl = txt(g, 'h(x*ₖ)', 532, (SY + ys) / 2, { size: 21, anchor: 'start', halo: 4 });
  hookup(hl, 'h(x*ₖ) = ' + depthOf(us).toFixed(2) + ' m', 'Depth of the sample level',
    'Every point of this thin strip sits at nearly the same depth h(x*ₖ), so the pressure across the strip is essentially the constant ρ·h(x*ₖ).');
  var yw = 292;
  g.line(sp.a, yw - 10, sp.a, yw + 10).stroke({ color: INK, width: 2 });
  g.line(sp.b, yw - 10, sp.b, yw + 10).stroke({ color: INK, width: 2 });
  g.line(sp.a, yw, sp.b, yw).stroke({ color: INK, width: 1.7 });
  hHead(g, sp.a, yw, -1); hHead(g, sp.b, yw, 1);
  txt(g, 'w(x*ₖ)', (sp.a + sp.b) / 2, yw, { size: 20, halo: 6 });
}

/* ---------------- animated accumulation panel -------------------- */
function drawPanelAnim(g, clip) {
  var n = state.n, m = (state.accumM == null) ? n : state.accumM, k;
  drawBlob(g);
  for (k = 1; k <= n; k++) {
    var y0 = byTo((k - 1) / n), y1 = byTo(k / n);
    var r = g.rect(PX1 - PX0 + 4, Math.max(1.2, y1 - y0)).move(PX0 - 2, y0)
      .fill(k <= m ? GREENDK : '#ffe6c2').opacity(k <= m ? 0.8 : 0.85)
      .stroke({ color: k <= m ? '#1d6b4d' : '#cfa268', width: (y1 - y0) > 4 ? 0.8 : 0.3 });
    r.clipWith(clip);
    (function (kk) {
      r.css('cursor', 'pointer')
        .on('mousemove', function (e) { showTooltip('strip ' + kk + ':  ρ·h·w·Δx = ' + kN(stripF(kk, n)) + ' kN', e); })
        .on('mouseleave', hideTooltip);
    })(k);
  }
  if (m > 0 && m < n) dashLine(g, byTo(m / n), AX, spanPix(m / n).b + 8);
  tickLab(g, PY_A, 'a'); tickLab(g, PY_B, 'b');
  var run = riemann(n, m);
  var gx = 556, gy0 = 70, gy1 = 262, gw = 24;
  g.rect(gw, gy1 - gy0).move(gx, gy0).fill('#ffffff').opacity(0.92).stroke({ color: '#444', width: 1.2 });
  var frac = clamp(run / EXACT, 0, 1);
  var bar = g.rect(gw, (gy1 - gy0) * frac).move(gx, gy0).fill(GREENDK).opacity(0.9);
  hookup(bar, 'running total = ' + kN(run) + ' kN  of  ' + kN(EXACT) + ' kN',
    'Accumulating the force',
    'The bar is the running sum of the strip forces, added from the surface downward. It climbs fastest where the plate is both wide and deep, because every strip contributes ρ·h·w·Δx.');
  txt(g, 'Σ', gx + gw / 2, gy0 - 14, { size: 18 });
  txt(g, kN(run) + ' kN', gx + gw / 2, gy1 + 14, { size: 13, style: 'normal' });
  txt(g, 'accumulated ' + m + ' of ' + n + ' strips', AX + 12, 44,
    { size: 18, style: 'normal', anchor: 'start', halo: 4.5 });
}

/* ---------------- readout (deliberately secondary) --------------- */
function drawReadout(g, rs) {
  var n = state.n, k = state.k, us = (k - 0.5) / n;
  var m = (state.view === 'anim' && state.accumM != null) ? state.accumM : n;
  var sum = riemann(n, m), full = riemann(n, n);
  var err = Math.abs(full - EXACT) / EXACT * 100;
  var box = g.rect(FIGW - 32, READH - 20).move(16, 4).radius(6)
    .fill('#f7f8f9').stroke({ color: '#cfd5da', width: 1 });
  hookup(box, 'Riemann sum vs. exact integral', 'From sum to integral',
    'Each strip contributes ρ·h(x*ₖ)·w(x*ₖ)·Δxₖ. Adding them gives the Riemann sum shown here; letting n → ∞ (Δxₖ → 0) makes the sum converge to the exact fluid force F = ∫ₐᵇ ρ h(x) w(x) dx, and the error collapses to zero.');
  txt(g, 'F ≈ Σ ρ h(x*ₖ) w(x*ₖ) Δxₖ      ⟶      F = ∫ₐᵇ ρ h(x) w(x) dx',
    FIGW / 2, 28, { size: 19 * rs, fill: '#333' });
  txt(g, 'n = ' + n + '    Σ = ' + kN(sum) + ' kN' + (m < n ? '  (' + m + ' of ' + n + ')' : '') +
    '    exact = ' + kN(EXACT) + ' kN    error = ' + err.toFixed(2) + '%',
    FIGW / 2, 52, { size: 13 * rs, style: 'normal', fill: '#666' });
  txt(g, 'strip k = ' + k + ':  h(x*ₖ) = ' + depthOf(us).toFixed(2) + ' m,  w(x*ₖ) = ' +
    widthM(us).toFixed(2) + ' m,  Δxₖ = ' + ((D_B - D_A) / n).toFixed(2) + ' m  →  ΔF = ' + kN(stripF(k, n)) + ' kN',
    FIGW / 2, 72, { size: 12.5 * rs, style: 'normal', fill: '#7a7a7a' });
}

/* ---------------- render ----------------------------------------- */
function render() {
  draw.clear();
  WATER = draw.gradient('linear', function (add) {
    add.stop(0, '#eaf7fd'); add.stop(0.5, '#bce4f5'); add.stop(1, '#7cc8ea');
  }).from(0, 0).to(0, 1);
  var clip = makeClip();
  var views = (state.view === 'all') ? ['a', 'b', 'c'] : [state.view];
  var totalH = views.length * BLOCK + READH;
  draw.viewbox(0, 0, FIGW, totalH);
  for (var i = 0; i < views.length; i++) {
    var v = views[i];
    var g = draw.group().translate(0, i * BLOCK);
    panelFrame(g);
    if (v === 'a') drawPanelA(g, clip);
    else if (v === 'b') drawPanelB(g, clip);
    else if (v === 'c') drawPanelC(g, clip);
    else drawPanelAnim(g, clip);
    var cap = v === 'a' ? '(a)' : v === 'b' ? '(b)' : v === 'c' ? '(c)' : '(d)  accumulating the strip forces';
    txt(g, cap, FIGW / 2, PANH + 20, { size: v === 'anim' ? 20 : 28 });
  }
  drawReadout(draw.group().translate(0, views.length * BLOCK), views.length > 1 ? 1.4 : 1);
}

/* ---------------- controls --------------------------------------- */
function setN(v) {
  state.n = clamp(Math.round(v), 1, 60);
  var ni = document.getElementById('nStripsInput'); if (ni) ni.value = state.n;
  var no = document.getElementById('nStripsVal'); if (no) no.value = state.n;
  var ki = document.getElementById('stripIndexInput'); if (ki) ki.max = state.n;
  if (state.k > state.n) setK(state.n);
  if (state.accumM != null) state.accumM = Math.min(state.accumM, state.n);
}
function setK(v) {
  state.k = clamp(Math.round(v), 1, state.n);
  var ki = document.getElementById('stripIndexInput'); if (ki) ki.value = state.k;
  var ko = document.getElementById('stripIndexVal'); if (ko) ko.value = state.k;
}
function update_nStrips(v) { stopAnim(); setN(v); if (state.view === 'anim') state.accumM = state.n; render(); }
function update_stripIndex(v) { setK(v); render(); }
function toggle_panelView(v) {
  stopAnim(); state.view = v;
  if (v === 'anim' && state.accumM == null) state.accumM = state.n;
  render();
}
function stopAnim() {
  if (animTimer) { clearInterval(animTimer); animTimer = null; }
  var b = document.getElementById('accumBtn'); if (b) b.textContent = '▶ Accumulate strip forces';
}
function startAnim() {
  stopAnim();
  state.accumM = 0; render();
  var b = document.getElementById('accumBtn'); if (b) b.textContent = '■ Stop';
  animTimer = setInterval(function () {
    state.accumM++;
    if (state.accumM >= state.n) { state.accumM = state.n; stopAnim(); }
    render();
  }, Math.max(40, Math.min(220, 2600 / state.n)));
}
function trigger_accumulate() {
  if (animTimer) { stopAnim(); state.accumM = state.n; render(); return; }
  if (state.view !== 'anim') {
    state.view = 'anim';
    var sel = document.getElementById('panelViewInput'); if (sel) sel.value = 'anim';
  }
  startAnim();
}

/* ---------------- guided demo ------------------------------------ */
var STEPS = [
  { t: 'The whole submerged plate',
    n: 'A flat plate hangs vertically in the fluid between depths a and b. At any depth x it has width w(x) and lies under depth h(x) of fluid — but pressure is <i>not</i> constant over the plate, so the force is not just pressure × area.',
    s: { view: 'a', n: 1, k: 1 } },
  { t: 'Slice it into horizontal strips',
    n: 'Partition the depth interval a = x₀ &lt; x₁ &lt; … &lt; xₙ = b. Each horizontal band Aₖ is thin enough that the depth — and therefore the pressure — barely changes across it.',
    s: { view: 'b', n: 8, k: 3 } },
  { t: 'Zoom in on the kth strip',
    n: 'Pick a sample depth x*ₖ inside [xₖ₋₁, xₖ]. Approximate the band by a rectangle of width w(x*ₖ) and thickness Δxₖ at the uniform depth h(x*ₖ): its force is ρ·h(x*ₖ)·w(x*ₖ)·Δxₖ.',
    s: { view: 'c', n: 8, k: 4 } },
  { t: 'Walk down the plate',
    n: 'Slide k from top to bottom: h(x*ₖ) grows steadily while w(x*ₖ) first grows, then shrinks through the bean-shaped notch. Deep <i>and</i> wide strips dominate the total force.',
    s: { view: 'all', n: 8, k: 7 } },
  { t: 'Add up the strips',
    n: 'Accumulating the strip forces from the surface downward builds the Riemann sum F ≈ Σ ρ h(x*ₖ) w(x*ₖ) Δxₖ; the running total climbs fastest through the widest, deepest part of the plate.',
    s: { view: 'anim', n: 8, k: 8 } },
  { t: 'Refine the partition',
    n: 'Raise n and the rectangles fill the plate almost exactly; the sum settles onto the exact value F = ∫ₐᵇ ρ h(x) w(x) dx and the error readout collapses toward zero.',
    s: { view: 'anim', n: 48, k: 24 } }
];
var stepIdx = 0;
function applyStep(i) {
  stepIdx = (i + STEPS.length) % STEPS.length;
  var st = STEPS[stepIdx];
  stopAnim();
  state.view = st.s.view;
  var sel = document.getElementById('panelViewInput'); if (sel) sel.value = st.s.view;
  setN(st.s.n); setK(st.s.k);
  state.accumM = state.n;
  document.getElementById('demoNarration').innerHTML =
    '<b>' + (stepIdx + 1) + '. ' + st.t + '</b><br>' + st.n;
  document.getElementById('stepLabel').textContent = 'Step ' + (stepIdx + 1) + ' / ' + STEPS.length;
  render();
  if (st.s.view === 'anim') startAnim();
}
function nextStep() { applyStep(stepIdx + 1); }
function prevStep() { applyStep(stepIdx - 1); }

/* ---------------- init ------------------------------------------- */
setN(8); setK(3);
document.getElementById('demoNarration').innerHTML = '<b>1. ' + STEPS[0].t + '</b><br>' + STEPS[0].n;
document.getElementById('stepLabel').textContent = 'Step 1 / ' + STEPS.length;
render();
window.__markRendered();
// @FIGURE_CODE_END

