// @FIGURE_CODE_BEGIN
/* ------------------------------------------------------------------ *
 *  Fluid force on a submerged plate — Riemann sum of horizontal strips
 * ------------------------------------------------------------------ */
var PW = 620, GH = 252, BLOCK = 300, CAPY = 281;   // one panel block (local units)
var SY = 16, AX = 92, RIGHT = 608;                  // surface y, depth axis x, right edge
var PY_A = 66, PY_B = 216, PX0 = 178, PX1 = 452;    // plate bounding box
var D_A = 2, D_B = 8, RHOG = 9810, PPM = 25;        // depths (m), weight density, px per metre
var SIDEW = 268, ROWH = 112;

var ORANGE = '#fbd196', TEAL = '#3ea7cb', RED = '#f2666c',
    GREEN = '#bfe2cd', GREENDK = '#3ba57c', INK = '#111';

var draw = SVG().addTo(document.getElementById('container')).size('100%', '100%');
var WATER = null;
var CW = 900, CH = 600;

function clamp(v, a, b) { return Math.max(a, Math.min(b, v)); }

/* ---------------- bean-shaped plate outline ---------------------- */
var RAW = [
  [0.50, 0.02], [0.68, 0.00], [0.85, 0.08], [0.95, 0.24], [0.99, 0.42],
  [0.96, 0.60], [0.88, 0.73], [0.77, 0.80], [0.68, 0.78], [0.60, 0.70],
  [0.53, 0.74], [0.45, 0.85], [0.36, 0.94], [0.26, 0.97], [0.16, 0.92],
  [0.07, 0.80], [0.02, 0.64], [0.01, 0.46], [0.05, 0.30], [0.14, 0.16],
  [0.27, 0.06], [0.38, 0.02]
];
function sampleClosed(pts, per) {
  var out = [], n = pts.length, i, j;
  for (i = 0; i < n; i++) {
    var p0 = pts[(i - 1 + n) % n], p1 = pts[i], p2 = pts[(i + 1) % n], p3 = pts[(i + 2) % n];
    for (j = 0; j < per; j++) {
      var t = j / per, t2 = t * t, t3 = t2 * t;
      var x = 0.5 * (2 * p1[0] + (-p0[0] + p2[0]) * t + (2 * p0[0] - 5 * p1[0] + 4 * p2[0] - p3[0]) * t2 + (-p0[0] + 3 * p1[0] - 3 * p2[0] + p3[0]) * t3);
      var y = 0.5 * (2 * p1[1] + (-p0[1] + p2[1]) * t + (2 * p0[1] - 5 * p1[1] + 4 * p2[1] - p3[1]) * t2 + (-p0[1] + 3 * p1[1] - 3 * p2[1] + p3[1]) * t3);
      out.push([x, y]);
    }
  }
  return out;
}
var POLY = (function () {
  var p = sampleClosed(RAW, 14), i;
  var x0 = 1e9, x1 = -1e9, y0 = 1e9, y1 = -1e9;
  for (i = 0; i < p.length; i++) {
    if (p[i][0] < x0) x0 = p[i][0]; if (p[i][0] > x1) x1 = p[i][0];
    if (p[i][1] < y0) y0 = p[i][1]; if (p[i][1] > y1) y1 = p[i][1];
  }
  for (i = 0; i < p.length; i++) { p[i][0] = (p[i][0] - x0) / (x1 - x0); p[i][1] = (p[i][1] - y0) / (y1 - y0); }
  return p;
})();
function bxTo(b) { return PX0 + b * (PX1 - PX0); }
function byTo(u) { return PY_A + u * (PY_B - PY_A); }
var BLOBD = (function () {
  var d = 'M' + bxTo(POLY[0][0]).toFixed(2) + ',' + byTo(POLY[0][1]).toFixed(2);
  for (var i = 1; i < POLY.length; i++) d += 'L' + bxTo(POLY[i][0]).toFixed(2) + ',' + byTo(POLY[i][1]).toFixed(2);
  return d + 'Z';
})();
function rowXs(u) {
  u = clamp(u, 0.0008, 0.9992);
  var xs = [], N = POLY.length, i;
  for (i = 0; i < N; i++) {
    var a = POLY[i], b = POLY[(i + 1) % N];
    if ((a[1] <= u && b[1] > u) || (b[1] <= u && a[1] > u)) {
      var t = (u - a[1]) / (b[1] - a[1]);
      xs.push(a[0] + t * (b[0] - a[0]));
    }
  }
  xs.sort(function (p, q) { return p - q; });
  return xs;
}
function spanPix(u) {
  var xs = rowXs(u);
  if (!xs.length) return { a: bxTo(0.5), b: bxTo(0.5), xs: [] };
  return { a: bxTo(xs[0]), b: bxTo(xs[xs.length - 1]), xs: xs };
}
function widthM(u) {
  var xs = rowXs(u), s = 0;
  for (var i = 0; i + 1 < xs.length; i += 2) s += (xs[i + 1] - xs[i]);
  return s * (PX1 - PX0) / PPM;
}
function depthOf(u) { return D_A + u * (D_B - D_A); }
function stripF(k, n) { var u = (k - 0.5) / n; return RHOG * depthOf(u) * widthM(u) * (D_B - D_A) / n; }
function riemann(n, m) { if (m == null) m = n; var s = 0; for (var k = 1; k <= m; k++) s += stripF(k, n); return s; }
var EXACT = integrateSimpson(function (u) { return RHOG * depthOf(u) * widthM(u) * (D_B - D_A); }, 0.0005, 0.9995, 2000);
function kN(v) { return (v / 1000).toFixed(0); }
function sub(v) { var s = '' + v, o = '', mp = '₀₁₂₃₄₅₆₇₈₉'; for (var i = 0; i < s.length; i++) o += mp[+s[i]]; return o; }

/* ---------------- small drawing helpers -------------------------- */
function txt(g, s, x, y, opt) {
  opt = opt || {};
  var t = g.text(s);
  t.font({ family: opt.family || 'Georgia,"Times New Roman",serif', size: opt.size || 22,
           style: opt.style || 'italic', weight: opt.weight || 'normal',
           anchor: opt.anchor || 'middle', leading: 1 });
  t.fill(opt.fill || INK);
  t.attr('dominant-baseline', 'central');
  t.attr('x', x); t.attr('y', y);
  var ts = t.node.querySelector('tspan');
  if (ts) { ts.setAttribute('x', x); ts.setAttribute('dy', 0); }
  if (opt.halo) t.attr({ 'paint-order': 'stroke', stroke: '#fff', 'stroke-width': opt.halo, 'stroke-linejoin': 'round' });
  return t;
}
function hookup(el, tip, ttl, body) {
  el.css('cursor', 'pointer')
    .on('mousemove', function (e) { showTooltip(tip, e); })
    .on('mouseleave', hideTooltip)
    .on('click', function () { showPopup(ttl, body); });
  return el;
}
function vHead(g, x, y, dir, color, s) {
  s = s || 6;
  g.polygon([[x - s * 0.8, y - dir * s * 1.7], [x + s * 0.8, y - dir * s * 1.7], [x, y]]).fill(color || INK);
}
function hHead(g, x, y, dir, color, s) {
  s = s || 6;
  g.polygon([[x - dir * s * 1.7, y - s * 0.8], [x - dir * s * 1.7, y + s * 0.8], [x, y]]).fill(color || INK);
}
function vDbl(g, x, y1, y2, color, w) {
  g.line(x, y1, x, y2).stroke({ color: color || INK, width: w || 2 });
  vHead(g, x, y1, -1, color); vHead(g, x, y2, 1, color);
}
function dashLine(g, y, x1, x2, w) {
  g.line(x1, y, x2, y).stroke({ color: RED, width: w || 2.3, dasharray: '9,6' });
}
function wave(g, y) {
  var d = 'M' + AX + ',' + y, x = AX, up = true;
  while (x < RIGHT - 4) { d += ' q 5 ' + (up ? -4.5 : 4.5) + ' 10 0'; x += 10; up = !up; }
  g.path(d).fill('none').stroke({ color: INK, width: 2 });
}
function tickLab(g, y, s, size) {
  g.line(AX - 11, y, AX, y).stroke({ color: INK, width: 2 });
  return txt(g, s, AX - 16, y, { size: size || 26, anchor: 'end', halo: 4 });
}
function drawBlob(g) {
  var p = g.path(BLOBD).fill(ORANGE).stroke({ color: INK, width: 2.4 });
  hookup(p, 'Submerged plate: from depth a = ' + D_A + ' m to b = ' + D_B + ' m; width w(x) varies with depth.',
    'The submerged plate',
    'The plate hangs vertically in the fluid, its top edge at depth a and its bottom at depth b. At depth x it is w(x) metres wide and lies under h(x) = x metres of fluid, so the pressure ρ·h(x) on it changes continuously from top to bottom.');
  return p;
}
function makeClip() { var c = draw.clip(); c.add(draw.path(BLOBD)); return c; }

/* ---------------- state ------------------------------------------ */
var state = { view: 'all', n: 8, k: 3, accumM: null };
var animTimer = null;

/* ---------------- panel chrome ----------------------------------- */
function panelFrame(g) {
  var w = g.rect(RIGHT - AX, GH - SY).move(AX, SY).fill(WATER);
  hookup(w, 'Fluid at rest: pressure at depth h equals ρ·h — it grows linearly downward.',
    'Pressure grows with depth',
    'In a fluid at rest the pressure at depth h below the surface is ρh, where ρ is the weight density of the fluid. Because that pressure differs at every depth of the plate, the total force is not pressure × area; it must be accumulated band by band.');
  wave(g, SY);
  g.line(AX, 6, AX, 244).stroke({ color: INK, width: 2.6 });
  g.polygon([[AX - 7, 243], [AX + 7, 243], [AX, 256]]).fill(INK);
}

/* ---------------- panel (a) -------------------------------------- */
function drawPanelA(g, clip) {
  var u = clamp((state.k - 0.5) / state.n, 0.16, 0.84);
  var y = byTo(u), sp = spanPix(u);
  dashLine(g, PY_A, AX, spanPix(0.004).b + 4);
  dashLine(g, PY_B, AX, spanPix(0.996).b + 4);
  drawBlob(g);
  var ch = g.line(sp.a, y, sp.b, y).stroke({ color: TEAL, width: 2.6 });
  ch.clipWith(clip);
  hookup(ch, 'w(x) = ' + widthM(u).toFixed(2) + ' m at depth x = ' + depthOf(u).toFixed(2) + ' m',
    'The width function w(x)',
    'A horizontal cut of the plate at depth x has total length w(x). Every point of that cut lies at the same depth, so it feels the same pressure ρ·h(x) — which is exactly why horizontal strips are the right slices.');
  g.circle(12).center(sp.a, y).fill(INK);
  g.circle(12).center(sp.b, y).fill(INK);
  txt(g, 'w(x)', (sp.a + sp.b) / 2, y - 24, { size: 26, halo: 5 });
  g.line(sp.b + 8, y, 572, y).stroke({ color: INK, width: 1.5 });
  vDbl(g, 580, SY + 3, y);
  var hl = txt(g, 'h(x)', 566, Math.max((SY + y) / 2, SY + 26), { size: 26, anchor: 'end', halo: 5 });
  hookup(hl, 'h(x) = ' + depthOf(u).toFixed(2) + ' m  →  pressure ρh = ' + kN(RHOG * depthOf(u)) + ' kPa',
    'The depth function h(x)',
    'h(x) measures how much fluid lies above level x. Since the pressure there is ρ·h(x), deeper parts of the same plate are pushed on far harder than shallow parts.');
  tickLab(g, PY_A, 'a');
  tickLab(g, PY_B, 'b');
  tickLab(g, y, 'x');
}

/* ---------------- panel (b) -------------------------------------- */
function drawPanelB(g, clip) {
  var n = state.n, kSel = state.k, k, u, y, sp;
  drawBlob(g);
  var y0 = byTo((kSel - 1) / n), y1 = byTo(kSel / n);
  var hb = g.rect(PX1 - PX0 + 4, Math.max(1.5, y1 - y0)).move(PX0 - 2, y0)
    .fill({ color: '#e08a2a', opacity: 0.18 }).stroke({ color: '#b06a15', width: 1.4 });
  hb.clipWith(clip);
  hookup(hb, 'band A' + sub(kSel) + ':  ΔF ≈ ' + kN(stripF(kSel, n)) + ' kN',
    'One band of the partition',
    'Band A' + sub(kSel) + ' lies between depths x' + sub(kSel - 1) + ' and x' + sub(kSel) + '. Its force is about ρ·h(x*ₖ)·w(x*ₖ)·Δxₖ, using one representative depth x*ₖ inside the band.');
  var band = (PY_B - PY_A) / n, thin = band < 7;
  for (k = 0; k <= n; k++) {
    u = k / n; y = byTo(u); sp = spanPix(u === 0 ? 0.004 : (u === 1 ? 0.996 : u));
    dashLine(g, y, AX, (k === 0 || k === n) ? sp.b + 3 : sp.a + 2, thin ? 1.1 : 2.1);
    if (k > 0 && k < n) {
      var cl = g.line(sp.a, y, sp.b, y).stroke({ color: TEAL, width: thin ? 0.9 : 1.7 });
      cl.clipWith(clip);
    }
  }
  var labs = [];
  if (band >= 14) { if (n <= 5) { for (k = 0; k <= n; k++) labs.push(k); } else { labs = [0, 1, 2, 3, n - 1, n]; } }
  else { labs = [0, n]; }
  for (var i = 0; i < labs.length; i++) {
    k = labs[i]; y = byTo(k / n);
    var s = (k === 0) ? 'a = x₀' : (k === n ? 'b = xₙ' : (k === n - 1 ? 'xₙ₋₁' : 'x' + sub(k)));
    tickLab(g, y, s, 22);
  }
  if (n > 5) {
    var ya = byTo(Math.min(3, n) / n), yb = byTo((n - 1) / n);
    if (yb - ya > 38) for (var d = 0; d < 3; d++) g.circle(4).center(AX - 34, ya + (yb - ya) * (0.32 + 0.18 * d)).fill(INK);
  }
  if (band >= 13) {
    var show = [];
    if (n <= 5) { for (k = 1; k <= n; k++) show.push(k); }
    else { show = [1, 2, 3, n]; }
    if (show.indexOf(kSel) === -1) show.push(kSel);
    for (var j = 0; j < show.length; j++) {
      k = show[j];
      var uc = (k - 0.5) / n, yc = byTo(uc), spc = spanPix(uc);
      var cx = (spc.a + spc.b) / 2;
      if (k === n) cx = spc.a + (spc.b - spc.a) * 0.32;
      txt(g, 'A' + (k === n ? 'ₙ' : sub(k)), cx, yc, { size: 22, halo: 4 });
    }
    if (n > 5) {
      var ym = byTo(0.58), xm = bxTo(0.56);
      for (var e = 0; e < 3; e++) g.circle(4.5).center(xm, ym + 13 * e).fill(INK);
    }
  }
}

/* ---------------- panel (c) -------------------------------------- */
function drawPanelC(g, clip) {
  var n = state.n, k = state.k;
  var u0 = (k - 1) / n, u1 = k / n, us = (k - 0.5) / n;
  var trueTh = byTo(u1) - byTo(u0);
  var th = Math.max(trueTh, 13);                 // close-up: keep the strip visible
  var ys = byTo(us), r0 = ys - th / 2, r1 = ys + th / 2, sp = spanPix(us);
  drawBlob(g);
  var rect = g.rect(sp.b - sp.a, th).move(sp.a, r0).fill(GREEN).opacity(0.95);
  rect.clipWith(clip);
  hookup(rect, 'ΔF ≈ ρ·h·w·Δx = ' + kN(stripF(k, n)) + ' kN' + (th > trueTh + 0.6 ? '  (close-up: drawn thicker)' : ''),
    'The kth strip',
    'Replace the curved band by a rectangle of width w(x*ₖ) and thickness Δxₖ sitting at the single depth h(x*ₖ). Its pressure is essentially constant, so its force is simply ρ·h(x*ₖ)·w(x*ₖ)·Δxₖ. In this close-up very thin strips are drawn slightly thicker so the geometry stays visible.');
  g.line(sp.a, r0, sp.b, r0).stroke({ color: INK, width: 1.8 });
  g.line(sp.a, r1, sp.b, r1).stroke({ color: INK, width: 1.8 });
  g.line(sp.a, r0, sp.a, r1).stroke({ color: INK, width: 1.4 });
  g.line(sp.b, r0, sp.b, r1).stroke({ color: INK, width: 1.4 });
  dashLine(g, ys, AX, sp.b);
  g.circle(11).center(sp.a, ys).fill(INK);
  g.circle(11).center(sp.b, ys).fill(INK);
  g.circle(11).center(AX, ys).fill(INK);
  tickLab(g, PY_A, 'a');
  tickLab(g, PY_B, 'b');
  txt(g, 'x*ₖ', AX - 16, ys, { size: 25, anchor: 'end', halo: 4 });
  txt(g, 'xₖ₋₁', AX + 15, r0 - 14, { size: 20, anchor: 'start', halo: 4 });
  txt(g, 'xₖ', AX + 15, r1 + 14, { size: 20, anchor: 'start', halo: 4 });

  /* Δxₖ measure just right of the strip */
  var axp = sp.b + 16;
  g.line(axp, r0 - 22, axp, r0).stroke({ color: INK, width: 1.7 });
  vHead(g, axp, r0, 1, INK, 5);
  g.line(axp, r1 + 22, axp, r1).stroke({ color: INK, width: 1.7 });
  vHead(g, axp, r1, -1, INK, 5);
  var dl = txt(g, 'Δxₖ', axp + 9, ys, { size: 21, anchor: 'start', halo: 5 });
  hookup(dl, 'Δxₖ = ' + ((D_B - D_A) / n).toFixed(3) + ' m', 'Strip thickness',
    'Δxₖ is the depth-thickness of the band. Shrinking it (larger n) makes the constant-pressure assumption ever more accurate — that is what turns the sum into an integral.');

  /* long h(x*ₖ) arrow at the far right, label to its left */
  g.line(542, ys, 572, ys).stroke({ color: INK, width: 1.3 });
  vDbl(g, 580, SY + 3, ys);
  var hy = Math.max((SY + ys) / 2, SY + 26);
  var hl = txt(g, 'h(x*ₖ)', 566, hy, { size: 23, anchor: 'end', halo: 5 });
  hookup(hl, 'h(x*ₖ) = ' + depthOf(us).toFixed(2) + ' m  →  ρh = ' + kN(RHOG * depthOf(us)) + ' kPa',
    'Depth of the sample level',
    'Every point of this thin strip sits at nearly the same depth h(x*ₖ), so the pressure across the strip is essentially the constant ρ·h(x*ₖ).');

  /* w(x*ₖ) measure below the plate */
  var yw = 238;
  g.line(sp.a, yw - 10, sp.a, yw + 10).stroke({ color: INK, width: 2 });
  g.line(sp.b, yw - 10, sp.b, yw + 10).stroke({ color: INK, width: 2 });
  g.line(sp.a, yw, sp.b, yw).stroke({ color: INK, width: 1.7 });
  hHead(g, sp.a, yw, -1); hHead(g, sp.b, yw, 1);
  var wl = txt(g, 'w(x*ₖ)', (sp.a + sp.b) / 2, yw, { size: 23, halo: 7 });
  hookup(wl, 'w(x*ₖ) = ' + widthM(us).toFixed(2) + ' m', 'Width of the strip',
    'The rectangle keeps the plate’s actual width at the sample depth, so its area is w(x*ₖ)·Δxₖ and its force is that area times the pressure ρ·h(x*ₖ).');
}

/* ---------------- animated accumulation panel -------------------- */
function drawPanelAnim(g, clip) {
  var n = state.n, m = (state.accumM == null) ? n : state.accumM, k;
  drawBlob(g);
  for (k = 1; k <= n; k++) {
    var y0 = byTo((k - 1) / n), y1 = byTo(k / n);
    var r = g.rect(PX1 - PX0 + 4, Math.max(1.2, y1 - y0)).move(PX0 - 2, y0)
      .fill(k <= m ? GREENDK : '#ffe6c2').opacity(k <= m ? 0.8 : 0.85)
      .stroke({ color: k <= m ? '#1d6b4d' : '#cfa268', width: (y1 - y0) > 4 ? 0.8 : 0.3 });
    r.clipWith(clip);
    (function (kk) {
      r.css('cursor', 'pointer')
        .on('mousemove', function (e) { showTooltip('strip ' + kk + ':  ρ·h·w·Δx = ' + kN(stripF(kk, n)) + ' kN', e); })
        .on('mouseleave', hideTooltip);
    })(k);
  }
  if (m > 0 && m < n) dashLine(g, byTo(m / n), AX, spanPix(m / n).b + 8);
  tickLab(g, PY_A, 'a'); tickLab(g, PY_B, 'b');
  var run = riemann(n, m);
  var gx = 540, gy0 = 56, gy1 = 216, gw = 26;
  g.rect(gw, gy1 - gy0).move(gx, gy0).fill('#ffffff').opacity(0.92).stroke({ color: '#444', width: 1.2 });
  var frac = clamp(run / EXACT, 0, 1);
  var bar = g.rect(gw, (gy1 - gy0) * frac).move(gx, gy0).fill(GREENDK).opacity(0.9);
  hookup(bar, 'running total = ' + kN(run) + ' kN  of  ' + kN(EXACT) + ' kN',
    'Accumulating the force',
    'The bar is the running sum of the strip forces, added from the surface downward. It climbs fastest where the plate is both wide and deep, because every strip contributes ρ·h·w·Δx.');
  txt(g, 'Σ', gx + gw / 2, gy0 - 16, { size: 22, halo: 4 });
  txt(g, kN(run) + ' kN', gx + gw / 2, gy1 + 16, { size: 17, style: 'normal', halo: 4 });
  txt(g, 'accumulated ' + m + ' of ' + n + ' strips', AX + 14, 40,
    { size: 20, style: 'normal', anchor: 'start', halo: 5 });
}

/* ---------------- readout (secondary, but legible) --------------- */
function readoutData() {
  var n = state.n, k = state.k, us = (k - 0.5) / n;
  var m = (state.view === 'anim' && state.accumM != null) ? state.accumM : n;
  return {
    n: n, k: k, m: m, us: us,
    sum: riemann(n, m), full: riemann(n, n),
    dx: (D_B - D_A) / n, h: depthOf(us), w: widthM(us), dF: stripF(k, n)
  };
}
function readoutHook(el) {
  hookup(el, 'Riemann sum vs. exact integral', 'From sum to integral',
    'Each strip contributes ρ·h(x*ₖ)·w(x*ₖ)·Δxₖ. Adding them gives the Riemann sum shown here; letting n → ∞ (Δxₖ → 0) makes the sum converge to the exact fluid force F = ∫ₐᵇ ρ h(x) w(x) dx, and the error collapses to zero.');
}
function buildReadoutColumn(g, w) {
  var d = readoutData(), H = 442;
  var box = g.rect(w, H).move(0, 0).radius(9).fill('#f7f8f9').stroke({ color: '#cfd5da', width: 1.3 });
  readoutHook(box);
  var cx = w / 2, err = Math.abs(d.full - EXACT) / EXACT * 100;
  txt(g, 'Riemann sum → integral', cx, 28, { size: 21, style: 'normal', weight: 'bold', family: 'sans-serif', fill: '#333' });
  g.line(16, 44, w - 16, 44).stroke({ color: '#dfe3e7', width: 1 });
  txt(g, 'F ≈ Σ ρ h(x*ₖ) w(x*ₖ) Δxₖ', cx, 74, { size: 21, fill: '#222' });
  txt(g, 'n → ∞   ⇓', cx, 106, { size: 19, style: 'normal', fill: '#666' });
  txt(g, 'F = ∫ₐᵇ ρ h(x) w(x) dx', cx, 138, { size: 21, fill: '#222' });
  g.line(16, 162, w - 16, 162).stroke({ color: '#dfe3e7', width: 1 });
  var lines = [
    'n = ' + d.n + '   Δxₖ = ' + d.dx.toFixed(2) + ' m',
    'Σ = ' + kN(d.sum) + ' kN' + (d.m < d.n ? '  (' + d.m + '/' + d.n + ')' : ''),
    'exact = ' + kN(EXACT) + ' kN',
    'error = ' + err.toFixed(2) + ' %'
  ];
  for (var i = 0; i < lines.length; i++)
    txt(g, lines[i], cx, 190 + i * 28, { size: 20, style: 'normal', fill: '#555' });
  g.line(16, 310, w - 16, 310).stroke({ color: '#dfe3e7', width: 1 });
  var l2 = [
    'strip k = ' + d.k,
    'h(x*ₖ) = ' + d.h.toFixed(2) + ' m',
    'w(x*ₖ) = ' + d.w.toFixed(2) + ' m',
    'ΔF = ' + kN(d.dF) + ' kN'
  ];
  for (var j = 0; j < l2.length; j++)
    txt(g, l2[j], cx, 338 + j * 28, { size: 20, style: 'normal', fill: '#777' });
  return H;
}
function buildReadoutRow(g, w) {
  var d = readoutData(), H = 104;
  var box = g.rect(w, H).move(0, 0).radius(8).fill('#f7f8f9').stroke({ color: '#cfd5da', width: 1.3 });
  readoutHook(box);
  var cx = w / 2, err = Math.abs(d.full - EXACT) / EXACT * 100;
  txt(g, 'F ≈ Σ ρ h(x*ₖ) w(x*ₖ) Δxₖ      ⟶      F = ∫ₐᵇ ρ h(x) w(x) dx', cx, 28, { size: 25, fill: '#222' });
  txt(g, 'n = ' + d.n + '    Σ = ' + kN(d.sum) + ' kN' + (d.m < d.n ? ' (' + d.m + '/' + d.n + ')' : '') +
    '    exact = ' + kN(EXACT) + ' kN    error = ' + err.toFixed(2) + ' %',
    cx, 58, { size: 21, style: 'normal', fill: '#555' });
  txt(g, 'strip k = ' + d.k + ':  h(x*ₖ) = ' + d.h.toFixed(2) + ' m,  w(x*ₖ) = ' + d.w.toFixed(2) +
    ' m,  Δxₖ = ' + d.dx.toFixed(2) + ' m  →  ΔF = ' + kN(d.dF) + ' kN',
    cx, 84, { size: 20, style: 'normal', fill: '#777' });
  return H;
}

/* ---------------- render ----------------------------------------- */
function render() {
  draw.clear();
  WATER = draw.gradient('linear', function (add) {
    add.stop(0, '#eaf7fd'); add.stop(0.5, '#bce4f5'); add.stop(1, '#7cc8ea');
  }).from(0, 0).to(0, 1);
  var clip = makeClip();

  var views = (state.view === 'all') ? ['a', 'b', 'c'] : [state.view];
  var N = views.length;
  var VW = 1000, VH = clamp(Math.round(1000 * CH / Math.max(1, CW)), 420, 2600);
  draw.viewbox(0, 0, VW, VH);

  var stackH = N * BLOCK, pad = 10;
  var leftW = VW - SIDEW - 24;
  var sSide = Math.min((leftW - pad) / PW, (VH - 2 * pad) / stackH);
  var sRow = Math.min((VW - 2 * pad) / PW, (VH - ROWH - 2 * pad) / stackH);
  var side = sSide >= sRow;
  var s = Math.min(side ? sSide : sRow, 2.6);

  var blockW = PW * s, blockH = stackH * s;
  var ox = side ? Math.max(pad, (leftW - blockW) / 2) : (VW - blockW) / 2;
  var oy = side ? (VH - blockH) / 2 : Math.max(pad, (VH - ROWH - blockH) / 2);

  for (var i = 0; i < N; i++) {
    var v = views[i];
    var g = draw.group().attr('transform',
      'translate(' + ox.toFixed(2) + ',' + (oy + i * BLOCK * s).toFixed(2) + ') scale(' + s.toFixed(4) + ')');
    panelFrame(g);
    if (v === 'a') drawPanelA(g, clip);
    else if (v === 'b') drawPanelB(g, clip);
    else if (v === 'c') drawPanelC(g, clip);
    else drawPanelAnim(g, clip);
    var cap = v === 'a' ? '(a)' : v === 'b' ? '(b)' : v === 'c' ? '(c)' : '(d)  accumulating the strip forces';
    txt(g, cap, (AX + RIGHT) / 2, CAPY, { size: v === 'anim' ? 22 : 30 });
  }

  /* readout */
  var rg = draw.group();
  if (side) {
    var Hc = buildReadoutColumn(rg, SIDEW);
    var rs = Math.min(1, (VH - 20) / Hc);
    rg.attr('transform', 'translate(' + (VW - SIDEW - 10) + ',' + ((VH - Hc * rs) / 2).toFixed(2) +
      ') scale(' + rs.toFixed(4) + ')');
  } else {
    var rw = clamp(blockW, 620, VW - 20);
    var Hr = buildReadoutRow(rg, 640);
    var rr = Math.min(rw / 640, (ROWH - 8) / Hr);
    rg.attr('transform', 'translate(' + ((VW - 640 * rr) / 2).toFixed(2) + ',' +
      (oy + blockH + 8).toFixed(2) + ') scale(' + rr.toFixed(4) + ')');
  }
}

/* ---------------- controls --------------------------------------- */
function setN(v) {
  state.n = clamp(Math.round(v), 1, 60);
  var ni = document.getElementById('nStripsInput'); if (ni) ni.value = state.n;
  var no = document.getElementById('nStripsVal'); if (no) no.value = state.n;
  var ki = document.getElementById('stripIndexInput'); if (ki) ki.max = state.n;
  if (state.k > state.n) setK(state.n);
  if (state.accumM != null) state.accumM = Math.min(state.accumM, state.n);
}
function setK(v) {
  state.k = clamp(Math.round(v), 1, state.n);
  var ki = document.getElementById('stripIndexInput'); if (ki) ki.value = state.k;
  var ko = document.getElementById('stripIndexVal'); if (ko) ko.value = state.k;
}
function update_nStrips(v) { stopAnim(); setN(v); if (state.view === 'anim') state.accumM = state.n; render(); }
function update_stripIndex(v) { setK(v); render(); }
function toggle_panelView(v) {
  stopAnim(); state.view = v;
  if (v === 'anim' && state.accumM == null) state.accumM = state.n;
  render();
}
function stopAnim() {
  if (animTimer) { clearInterval(animTimer); animTimer = null; }
  var b = document.getElementById('accumBtn'); if (b) b.textContent = '▶ Accumulate strip forces';
}
function startAnim() {
  stopAnim();
  state.accumM = 0; render();
  var b = document.getElementById('accumBtn'); if (b) b.textContent = '■ Stop';
  animTimer = setInterval(function () {
    state.accumM++;
    if (state.accumM >= state.n) { state.accumM = state.n; stopAnim(); }
    render();
  }, Math.max(40, Math.min(220, 2600 / state.n)));
}
function trigger_accumulate() {
  if (animTimer) { stopAnim(); state.accumM = state.n; render(); return; }
  if (state.view !== 'anim') {
    state.view = 'anim';
    var sel = document.getElementById('panelViewInput'); if (sel) sel.value = 'anim';
  }
  startAnim();
}

